# connections, a bare connection without a cursor, and list/mutation payloads.
type Query {
	posts(first: Int, after: String, last: Int, before: String): PostConnection!
	fwd(first: Int, after: String): FwdConnection!
	back(last: Int, before: String): BackConnection!
	paged(offset: Int, limit: Int): OffsetConnection!
	bare(first: Int, after: String): BareConnection!
	feed: [Post!]!
	search(term: String!): [SearchResult!]!
	node(id: ID!): Node
	me: User!
	thing(
		int: Int
		float: Float
		string: String
		nothing: String
		bool: Boolean
		kind: Kind
		list: [Int!]
		empty: [Int!]
		object: Filter
	): Post!
}

enum Kind {
	Draft
	Published
}

input Filter {
	term: String
	kinds: [Kind!]
	limit: Int
	nested: Filter
}

interface Node {
	id: ID!
}

type User implements Node {
	id: ID!
	name: String!
	pinned: [Post!]!
}

type Post implements Node {
	id: ID!
	title: String!
	subtitle: String
	body: String!
	author: User!
	comments: [Comment!]!
}

type Comment implements Node {
	id: ID!
	text: String!
	author: User!
}

union SearchResult = Post | User

type PostConnection {
	edges: [PostEdge!]!
	nodes: [Post!]!
	pageInfo: PageInfo!
}

type FwdConnection {
	edges: [PostEdge!]!
	pageInfo: PageInfo!
	first: Int
	after: String
}

type BackConnection {
	edges: [PostEdge!]!
	pageInfo: PageInfo!
	last: Int
	before: String
}

type OffsetConnection {
	edges: [PostEdge!]!
	pageInfo: PageInfo!
	offset: Int
	limit: Int
}

type BareConnection {
	edges: [BareEdge!]!
	pageInfo: PageInfo!
}

type PostEdge {
	cursor: String
	node: Post!
}

type BareEdge {
	node: Post!
}

type PageInfo {
	endCursor: String
	hasNextPage: Boolean!
	hasPreviousPage: Boolean!
	startCursor: String!
}

type Mutation {
	createPost(input: PostInput!): CreatePostPayload
	deletePost(id: ID!): DeletePostPayload
}

input PostInput {
	title: String!
	tags: [String!]
}

type CreatePostPayload {
	post: Post
}

type DeletePostPayload {
	post: Post
}

type Subscription {
	postAdded: Post!
}

inputs.text:
fragment PostCard on Post {
	id
	title
	author {
		id
		name
	}
}

fragment PostWithAuthor on Post {
	...PostCard
	comments {
		id
		text
	}
}

mutation CreatePost($input: PostInput!) {
	createPost(input: $input) {
		post @optimisticKey {
			id
			title
			...Posts_insert
			...Posts_toggle @append
		}
	}
}

mutation DeletePost($id: ID!) {
	deletePost(id: $id) {
		post {
			id
			...Posts_remove @prepend
			...Pinned_toggle @listTarget(name: "Pinned")
		}
	}
}

query NodeView($id: ID!, $withBody: Boolean! = true) {
	node(id: $id) @required {
		id
		... on Post @defer(label: "body") {
			title
			subtitle @required
			author {
				name @required
			}
			byline: author @required {
				id
			}
		}
		... on Comment @defer(if: $withBody) {
			text
		}
		... on User @defer {
			name
		}
	}
}

query Bare {
	bare(first: 10) @paginate(mode: SinglePage, name: "Bare_Items") {
		edges {
			node {
				id
			}
		}
	}
}

query Conditional($withAuthor: Boolean!, $withComments: Boolean!) {
	feed {
		id
		...PostCard @include(if: $withAuthor)
		...PostCard @skip(if: $withComments)
		...PostCard
	}
}

query Deduped @dedupe(cancelFirst: true, match: all) {
	feed {
		id
	}
}

query Deferred($id: ID!, $withCard: Boolean! = false) {
	node(id: $id) {
		...PostCard @defer(if: $withCard, label: "card")
		...PostWithAuthor @defer(label: "PostCard")
		...PostCard @defer
	}
}

query Detail($id: ID!) {
	node(id: $id) {
		... on Post {
			...PostWithAuthor
		}
	}
}

query Directions {
	back(last: 2) @paginate(mode: Infinite, name: "Back_Items") {
		edges {
			node {
				id
			}
		}
	}
}

query Feed($first: Int = 10) {
	posts(first: $first) @paginate(mode: Infinite, name: "Feed_Posts") {
		edges @loading(count: 3) {
			node {
				id
				title
				...PostCard
			}
		}
		pageInfo {
			hasNextPage
			startCursor
		}
	}
}

query FeedStream {
	feed @stream {
		id
	}
}

query PostList @cache(policy: CacheOnly, partial: true) {
	feed @list(name: "Posts") {
		id
		title
	}
	posts(first: 5) @list(name: "Paged") {
		edges {
			node {
				id
			}
		}
	}
	me {
		pinned @list(name: "Pinned") {
			id
		}
	}
}

query Loading($id: ID!) {
	node(id: $id) {
		id @loading
		... on Post {
			author @loading {
				name
			}
		}
	}
}

query Negated($withoutAuthor: Boolean!) {
	feed {
		id
		...PostCard @skip(if: $withoutAuthor)
	}
}

query NodesPaged {
	posts(first: 2) @paginate(name: "Nodes_Posts") {
		nodes {
			id
			title
		}
	}
}

query OffsetPage($offset: Int = 0, $limit: Int = 5) {
	paged(offset: $offset, limit: $limit) @paginate(name: "Offset_Paged") {
		edges {
			node {
				id
				...PostCard @mask_disable @required
			}
		}
	}
}

query PagedBare {
	posts(first: 3) @paginate(name: "Bare_Paged") {
		edges {
			node {
				id
			}
		}
	}
}

query PagedLiterals {
	fwd(first: 2) @paginate(mode: SinglePage, name: "Fwd_Literal") {
		edges {
			node {
				id
			}
		}
	}
}

query PagedNull {
	fwd(first: 1, after: null) @paginate(mode: SinglePage, name: "Fwd_Null") {
		edges {
			node {
				id
			}
		}
	}
}

query Search($term: String!) {
	search(term: $term) {
		... on Post {
			id
			title
		}
		... on User {
			id
			name
		}
	}
}

query Skipped($withTitle: Boolean!) {
	feed {
		id
		title @include(if: $withTitle)
		... {
			subtitle
		}
		... on Post @include(if: $withTitle) {
			body
		}
	}
}

query Streamed($id: ID!) {
	node(id: $id) {
		... on User {
			pinned @stream(initialCount: 1, label: "pinned") {
				id
				title
			}
		}
	}
}

subscription Watch {
	postAdded {
		id
		title
	}
}

