            node {
                __typename
                id
            }
        }
        nodes {
            __typename
            id
            title
        }
        pageInfo {
            __typename
            endCursor
            hasNextPage
            hasPreviousPage
            startCursor
        }
    }
}

query OffsetPage($offset: Int = 0, $limit: Int = 5, $first: Int, $after: String, $last: Int, $before: String) {
    paged(offset: $offset, limit: $limit, first: $first, after: $after, last: $last, before: $before) {
        __typename
        edges {
            __typename
            node {
                __typename
                id
                ...PostCard
            }
        }
        pageInfo {
            __typename
            endCursor
            hasNextPage
            hasPreviousPage
            startCursor
        }
    }
}

fragment PostCard on Post {
    __typename
    author {
        __typename
        id
        name
    }
    id
    title
}

query PagedBare($first: Int = 3, $after: String, $last: Int, $before: String) {
    posts(first: $first, after: $after, last: $last, before: $before) {
        __typename
        edges {
            __typename
            node {
                __typename
                id
            }
        }
        pageInfo {
            __typename
            endCursor
            hasNextPage
            hasPreviousPage
            startCursor
        }
    }
}

query PagedLiterals($first: Int = 2, $after: String, $last: Int, $before: String) {
    fwd(first: $first, after: $after, last: $last, before: $before) {
        __typename
        edges {
            __typename
            cursor
            node {
                __typename
                id
            }
        }
        pageInfo {
            __typename
            endCursor
            hasNextPage
            hasPreviousPage
            startCursor
        }
    }
}

query PagedNull($first: Int = 1, $after: String = null, $last: Int, $before: String) {
    fwd(first: $first, after: $after, last: $last, before: $before) {
        __typename
        edges {
            __typename
            cursor
            node {
                __typename
                id
            }
        }
        pageInfo {
            __typename
            endCursor
            hasNextPage
            hasPreviousPage
            startCursor
        }
    }
}

query Search($term: String!) {
    search(term: $term) {
        __typename
        ... on Post {
            __typename
            id
            title
        }
        ... on User {
            __typename
            id
            name
        }
    }
}

query Skipped($withTitle: Boolean!) {
    feed {
        __typename
        id
        title @include(if: $withTitle)
        ... {
            __typename
            subtitle
        }
        ... on Post @include(if: $withTitle) {
            __typename
            body
        }
    }
}

query Streamed($id: ID!) {
    node(id: $id) {
        __typename
        ... on User {
            __typename
            pinned @stream(initialCount: 1, label: "pinned") {
                __typename
                id
                title
            }
        }
    }
}

subscription Watch {
    postAdded {
        __typename
        id
        title
    }
}
